import java.util.Properties
import org.jetbrains.kotlin.gradle.dsl.JvmTarget

// xtmd-android: the Kotlin bindings to Extended Mark's native runtime (generated by UniFFI, with the runtime
// built for Android's processors, by ../../xtmd/build.sh into native/), our default Compose and
// Material 3 widgets for every core extern widget, and XtmdPage.
//
// Its unit tests hold the two check adapters, which run Compose under Robolectric on a plain JVM:
// `./gradlew :xtmd-android:checkAdapterArgs` writes ../build/check_adapter.args, the classpath
// target.yaml's `java @build/check_adapter.args …` starts them with.
plugins {
    alias(libs.plugins.android.library)
    alias(libs.plugins.kotlin.android)
    alias(libs.plugins.kotlin.compose)
    `maven-publish`
}

val native = layout.projectDirectory.dir("native")

android {
    namespace = "xtmd.android"
    compileSdk = 36
    // the build tools and NDK this box has (README): AGP would otherwise fetch its own defaults
    buildToolsVersion = "36.1.0"
    ndkVersion = "30.0.16248370"
    defaultConfig {
        minSdk = 26
        consumerProguardFiles("consumer-rules.pro")
    }
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
    buildFeatures { compose = true }
    sourceSets {
        getByName("main") {
            // uniffi-bindgen's xtmd/android/ffi/xtmd_android.kt, and libxtmd_android.so per processor
            java.srcDir(native.dir("kotlin"))
            jniLibs.srcDir(native.dir("jniLibs"))
        }
        getByName("test") {
            // the check packs' Android widgets (targets/checks/packs/*/android.kt), as an app adds a pack's
            java.srcDir(rootProject.file("../../checks/packs/badge"))
        }
    }
    testOptions { unitTests.isIncludeAndroidResources = true }
    lint { abortOnError = false }
    publishing { singleVariant("release") { withSourcesJar() } }
}

// Published as xtmd:xtmd-android: `./gradlew :xtmd-android:publish` writes it to ../build/repo, a
// Maven repository an app's build can name (README.md: the AAR).
afterEvaluate {
    publishing {
        publications {
            create<MavenPublication>("release") {
                from(components["release"])
                groupId = "xtmd"
                artifactId = "xtmd-android"
                version = "0.3.0"
            }
        }
        repositories { maven { url = uri(rootProject.layout.buildDirectory.dir("repo")) } }
    }
}

kotlin { compilerOptions { jvmTarget.set(JvmTarget.JVM_17) } }

dependencies {
    api(platform(libs.compose.bom))
    api(libs.compose.ui)
    api(libs.compose.foundation)
    api(libs.compose.material3)
    implementation("${libs.jna.aar.get()}@aar")

    // the real-time target, for its check adapter (CheckAdapter.kt: LiveCheckAdapter)
    testImplementation(project(":xtmd-android-live"))
    testImplementation(platform(libs.compose.bom))
    testImplementation(libs.compose.ui.test.junit4)
    testImplementation(libs.robolectric)
    testImplementation(libs.junit)
    // the plain jar: libjnidispatch for the host, which the AAR doesn't carry
    testImplementation(libs.jna)
    // ComponentActivity in the test manifest, for runAndroidComposeUiTest
    debugImplementation(libs.compose.ui.test.manifest)
}

// The native libraries and bindings must be there before anything compiles.
val nativeThere = tasks.register("checkNative") {
    val bindings = native.file("kotlin/xtmd/android/ffi/xtmd_android.kt").asFile
    doLast {
        if (!bindings.exists()) throw GradleException("no bindings in ${bindings.parent}: run targets/android/xtmd/build.sh first (README.md)")
    }
}
tasks.named("preBuild") { dependsOn(nativeThere) }

// The check adapters run as a plain JVM, not through Gradle: this compiles them and writes the
// exact classpath the unit tests run with, with the host's libxtmd_android.so on JNA's path, into
// ../build/check_adapter.args (target.yaml's `java @build/check_adapter.args xtmd.android.CheckAdapter`,
// and omnicui's targets/checks/targets/android/target.yaml).
tasks.register("checkAdapterArgs") {
    val test = tasks.named<Test>("testDebugUnitTest")
    // everything the unit tests need, the merged manifest and resources Robolectric reads included
    dependsOn(test.map { t -> t.taskDependencies.getDependencies(t) })
    val classpath = test.map { it.classpath }
    inputs.files(classpath)
    val out = rootProject.layout.buildDirectory.file("check_adapter.args")
    val config = layout.buildDirectory.dir("check_adapter/com/android/tools")
    val module = layout.projectDirectory.asFile
    val host = native.dir("host/linux-x86-64").asFile
    val liveHost = project(":xtmd-android-live").layout.projectDirectory.dir("native/host/linux-x86-64").asFile
    outputs.file(out)
    outputs.dir(config)
    doLast {
        // AGP's test_config.properties names its files relative to this module, where Gradle runs
        // the tests; the adapter runs from target.yaml's folder, so it gets one with whole paths,
        // ahead of AGP's on the classpath
        val agp = classpath.get().files.map { File(it, "com/android/tools/test_config.properties") }.first { it.exists() }
        val props = Properties().apply { agp.inputStream().use { load(it) } }
        for (k in props.stringPropertyNames()) {
            val v = props.getProperty(k)
            if (v.startsWith("build/")) props.setProperty(k, File(module, v).absolutePath)
        }
        val dir = config.get().asFile
        dir.mkdirs()
        File(dir, "test_config.properties").outputStream().use { props.store(it, "xtmd-android's check adapters: AGP's, with whole paths") }
        val cp = listOf(dir.parentFile.parentFile.parentFile) + classpath.get().files
        out.get().asFile.parentFile.mkdirs()
        out.get().asFile.writeText(
            listOf(
                "-Xmx2g",
                "-XX:+UseParallelGC",
                "-Djna.library.path=\"${host.absolutePath}${File.pathSeparator}${liveHost.absolutePath}\"",
                "-cp \"${cp.joinToString(File.pathSeparator) { it.absolutePath }}\"",
            ).joinToString("\n") + "\n",
        )
    }
}

// The unit tests load the host's libxtmd_android.so through JNA, as the check adapters do, and the
// real-time target's libxtmd_android_live.so.
tasks.withType<Test>().configureEach {
    val liveHost = project(":xtmd-android-live").layout.projectDirectory.dir("native/host/linux-x86-64").asFile
    systemProperty("jna.library.path", listOf(native.dir("host/linux-x86-64").asFile, liveHost).joinToString(File.pathSeparator) { it.absolutePath })
    maxHeapSize = "2g"
    // `-Pxtmd.jfr=<file>`: a Java Flight Recording of the tests, to see where their time goes
    System.getenv("XTMD_ANDROID_TRACE")?.let { environment("XTMD_ANDROID_TRACE", it) }
    (project.findProperty("xtmd.perf.only") as String?)?.let { systemProperty("xtmd.perf.only", it) }
    (project.findProperty("xtmd.jfr") as String?)?.let { jvmArgs("-XX:StartFlightRecording=filename=$it,settings=profile,jdk.ExecutionSample#period=1ms") }
}
